  8643	Elf32_Sym const *PackLinuxElf32::elf_lookup(char const *name) const
  8644	{
  8645	    if (hashtab && dynsym && dynstr) {
  8646	        unsigned const n_bucket = get_te32(&hashtab[0]);
  8647	        unsigned const *const buckets = &hashtab[2];
  8648	        unsigned const *const chains = &buckets[n_bucket];
  8649	        // Find the end of DT_HASH and DT_DYNSYM. Perhaps elf_find_table_size()
  8650	        // depends on too many valid input values?
  8651	        void const *l_hash = nullptr, *l_sym = nullptr;
  8652	        for (unsigned j = 0; j < DT_NUM; ++j) {
  8653	            void const *const ptr = dt_offsets[j] + (char const *)file_image.getVoidPtr();
  8654	            if (!l_hash && hashtab == ptr) {
  8655	                l_hash = dt_offsets[1+ j] + (char const *)file_image.getVoidPtr();
  8656	            }
  8657	            if (!l_sym && dynsym == ptr) {
  8658	                l_sym = dt_offsets[1+ j] + (char const *)file_image.getVoidPtr();
  8659	            }
  8660	            if (l_sym && l_hash)
  8661	                break;  // found both
  8662	            if (this->file_size == (off_t)dt_offsets[j])
  8663	                break;  // end sentinel
  8664	        }
  8665	        if (n_bucket) {
  8666	            unsigned const m = elf_hash(name) % n_bucket;
  8667	            unsigned n_visit = 0;
  8668	            unsigned si;
  8669	            if (l_hash <= &buckets[m])
  8670	                throwCantPack("bad DT_HASH %u", m);
  8671	            for (si= get_te32(&buckets[m]); si; si = get_te32(&chains[si])) {
  8672	                if (l_sym <= &dynsym[si])
  8673	                    throwCantPack("bad DT_HASH chain %d\n", si);
  8674	                char const *const p= get_dynsym_name(si, (unsigned)-1);
  8675	                if (p && 0==strcmp(name, p))
  8676	                    return &dynsym[si];
  8677	                if (l_sym <= &dynsym[n_visit++])
  8678	                    throwCantPack("circular DT_HASH chain %d\n", si);
  8679	            }
  8680	        }
  8681	    }
  8682	    if (gashtab && dynsym && dynstr) {
  8683	        unsigned const n_bucket = get_te32(&gashtab[0]);
  8684	        unsigned const symbias  = get_te32(&gashtab[1]);
  8685	        unsigned const n_bitmask = get_te32(&gashtab[2]);
  8686	        unsigned const gnu_shift = get_te32(&gashtab[3]);
  8687	        unsigned const *const bitmask = &gashtab[4];
  8688	        unsigned const *const buckets = &bitmask[n_bitmask];
  8689	        unsigned const *const hasharr = &buckets[n_bucket];
  8690	        if (31 < gnu_shift) {
  8691	            throwCantPack("bad gnu_shift %#x", gnu_shift);
  8692	        }
  8693	        if ((file_size + file_image) <= (void const *)hasharr) {
  8694	            throwCantPack("bad n_bucket %#x\n", n_bucket);
  8695	        }
  8696	        if (!n_bitmask
  8697	        || (unsigned)(file_size - ((char const *)bitmask - (char const *)(void const *)file_image))
  8698	                <= sizeof(unsigned)*n_bitmask ) {
  8699	            throwCantPack("bad n_bitmask %#x\n", n_bitmask);
  8700	        }
